'use strict';
(() => {
const data = window.WIKI_DATA;
const $ = (s, root = document) => root.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storage = {get(key){try{return localStorage.getItem(key)}catch{return null}},set(key,value){try{localStorage.setItem(key,value)}catch{}}};
let lang = storage.get('lp-wiki-language') === 'en' ? 'en' : 'zh';
const t = (zh, en) => lang === 'zh' ? zh : en;
const local = obj => obj[lang];
const arrow = '<span class="arrow" aria-hidden="true">↗</span>';
const forward = '<span class="arrow" aria-hidden="true">→</span>';
const cf = 'https://www.curseforge.com/minecraft/mc-mods/irons-spells-light-pollution';
const contact = {qqGroup:'748610283', email:'qq3561989295@163.com'};
const schoolNames = {ender:['末影','Ender'],holy:['神圣','Holy'],fire:['火焰','Fire'],lightning:['雷电','Lightning'],nature:['自然','Nature'],eldritch:['邪术','Eldritch'],evocation:['唤魔','Evocation'],blood:['鲜血','Blood']};
const familyNames = {gravity:['黑洞与引力','Gravity & black holes'],stellar:['恒星与天象','Stars & nebulae'],domain:['领域与仪式','Domains & rituals'],nature:['自然与巨兽','Nature & creatures'],arcane:['秘术与飞行','Arcana & flight']};
const rarityNames = {legendary:['传说','Legendary'],epic:['史诗','Epic'],rare:['稀有','Rare']};
const named = (map,key) => map[key] ? t(...map[key]) : key;
const spell = id => data.spells.find(s => s.id === id);
const fmt = n => Number(n).toLocaleString(lang === 'zh' ? 'zh-CN' : 'en-US', {maximumFractionDigits:2});
const icon = s => `<img class="spell-icon" src="${esc(s.icon)}" alt="" width="52" height="52" loading="lazy">`;
const pending = () => `<span class="pill pending">${t('1.7.7 待发布','1.7.7 preview')}</span>`;
const guideNames = {start:['开始游玩','Getting started'],scrolls:['卷轴与升级','Scrolls & upgrades'],equipment:['装备与施法','Equipment & casting'],flight:['飞行指南','Flight guide'],config:['配置与性能','Settings & performance'],faq:['常见问题','FAQ'],updates:['版本说明','Version notes'],credits:['关于与致谢','About & credits']};
const ingredientNames = {
 arcane_essence:['奥术精华','Arcane Essence'],blood_rune:['鲜血符文','Blood Rune'],ender_rune:['末影符文','Ender Rune'],evocation_rune:['唤魔符文','Evocation Rune'],fire_rune:['火焰符文','Fire Rune'],holy_rune:['神圣符文','Holy Rune'],legendary_ink:['传说墨水','Legendary Ink'],lightning_rune:['雷电符文','Lightning Rune'],nature_rune:['自然符文','Nature Rune'],rare_ink:['稀有墨水','Rare Ink'],amethyst_cluster:['紫水晶簇','Amethyst Cluster'],amethyst_shard:['紫水晶碎片','Amethyst Shard'],beacon:['信标','Beacon'],blaze_rod:['烈焰棒','Blaze Rod'],chain:['锁链','Chain'],clock:['时钟','Clock'],copper_ingot:['铜锭','Copper Ingot'],crying_obsidian:['哭泣的黑曜石','Crying Obsidian'],dragon_breath:['龙息',"Dragon’s Breath"],echo_shard:['回响碎片','Echo Shard'],end_crystal:['末地水晶','End Crystal'],end_rod:['末地烛','End Rod'],ender_eye:['末影之眼','Eye of Ender'],ender_pearl:['末影珍珠','Ender Pearl'],feather:['羽毛','Feather'],fire_charge:['火焰弹','Fire Charge'],glowstone:['荧石','Glowstone'],heart_of_the_sea:['海洋之心','Heart of the Sea'],iron_sword:['铁剑','Iron Sword'],lightning_rod:['避雷针','Lightning Rod'],lodestone:['磁石','Lodestone'],magma_block:['岩浆块','Magma Block'],mangrove_propagule:['红树胎生苗','Mangrove Propagule'],nautilus_shell:['鹦鹉螺壳','Nautilus Shell'],nether_star:['下界之星','Nether Star'],netherite_sword:['下界合金剑','Netherite Sword'],obsidian:['黑曜石','Obsidian'],paper:['纸','Paper'],phantom_membrane:['幻翼膜','Phantom Membrane'],prismarine_crystals:['海晶砂粒','Prismarine Crystals'],recovery_compass:['追溯指针','Recovery Compass'],sculk_catalyst:['幽匿催发体','Sculk Catalyst'],sculk_sensor:['幽匿感测体','Sculk Sensor'],sculk_shrieker:['幽匿尖啸体','Sculk Shrieker'],soul_lantern:['灵魂灯笼','Soul Lantern'],spyglass:['望远镜','Spyglass'],tinted_glass:['遮光玻璃','Tinted Glass'],torchflower:['火把花','Torchflower'],turtle_egg:['海龟蛋','Turtle Egg']
};
function ingredient(id){return window.WIKI_ITEMS[id]?.name[lang] || named(ingredientNames,id.split(':').pop())}
function itemMod(id){const ns=id.split(':')[0];return ns==='minecraft'?'Minecraft':ns==='irons_spellbooks'?"Iron’s Spells ’n Spellbooks":ns==='irons_spellbooks_light_pollution'?t('铁魔法：光污染','Iron’s Spells: Light Pollution'):ns}
function itemButton(id,name,css='ingredient'){
 const item=window.WIKI_ITEMS[id];
 return `<button type="button" class="${css} item-trigger" data-item="${esc(id)}" data-item-name="${esc(name)}" aria-label="${esc(name+' — '+itemMod(id))}">${item.render==='label'?`<span class="ingredient-label">${esc(name)}</span>`:`<img src="${esc(item.icon)}" alt="" width="64" height="64" loading="lazy" draggable="false">`}</button>`;
}
let tooltipTarget=null,tooltipTimer;
function hideItemTooltip(){clearTimeout(tooltipTimer);tooltipTarget?.removeAttribute('aria-describedby');tooltipTarget=null;$('#item-tooltip').hidden=true}
function showItemTooltip(target){
 clearTimeout(tooltipTimer);tooltipTarget?.removeAttribute('aria-describedby');tooltipTarget=target;
 const box=$('#item-tooltip');box.innerHTML=`<strong>${esc(target.dataset.itemName)}</strong><span>${esc(itemMod(target.dataset.item))}</span>`;
 box.hidden=false;target.setAttribute('aria-describedby','item-tooltip');
 const rect=target.getBoundingClientRect(),width=box.offsetWidth,height=box.offsetHeight;
 box.style.left=Math.max(12,Math.min(innerWidth-width-12,rect.left+rect.width/2-width/2))+'px';
 box.style.top=(rect.top>height+16?rect.top-height-10:rect.bottom+10)+'px';
}
function bindItems(){
 document.querySelectorAll('.item-trigger').forEach(target=>{
  target.addEventListener('pointerenter',()=>showItemTooltip(target));
  target.addEventListener('focus',()=>showItemTooltip(target));
  target.addEventListener('click',()=>showItemTooltip(target));
  target.addEventListener('pointerleave',()=>{if(document.activeElement!==target)tooltipTimer=setTimeout(hideItemTooltip,140)});
  target.addEventListener('blur',hideItemTooltip);
 });
}
function brand(){return `<a class="brand" href="#/" aria-label="${t('光污染百科首页','Light Pollution Wiki home')}"><img src="assets/mark.svg" alt="" width="40" height="40"><div><strong>${t('光污染','Light Pollution')}</strong><span>SPELL ATLAS & PLAYER WIKI</span></div></a>`}
function contactDetails(){return `<address class="contact-details" aria-label="${t('联系方式','Contact')}"><p><span>${t('中国 QQ 群','China QQ group')}：</span><span>${contact.qqGroup}</span></p><p><span>${t('邮箱','Email')}：</span><a href="mailto:${contact.email}">${contact.email}</a></p></address>`}
function chrome(route){
 document.documentElement.lang = lang === 'zh' ? 'zh-CN' : 'en';
 const nav=[['/spells',t('法术图鉴','Spell atlas')],['/guide/start',t('游玩指南','Player guide')],['/text-effects',t('文字特效','Text effects')],['/equipment',t('武器','Weapons')],['/guide/updates',t('版本说明','Version notes')]];
 $('#header').innerHTML=`<div class="container nav-wrap">${brand()}<nav id="navigation" class="nav-links" aria-label="${t('主导航','Main navigation')}">${nav.map(([url,label])=>`<a href="#${url}" ${route===url||url==='/spells'&&route.startsWith('/spell/')||url==='/equipment'&&route.startsWith('/equipment/')?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="nav-tools"><button class="language" id="language" aria-label="${t('Switch to English','切换到简体中文')}" lang="${t('en','zh-CN')}">${t('EN','中文')} <span aria-hidden="true">⌄</span></button><a class="nav-download" href="${cf}" target="_blank" rel="noopener noreferrer">${t('下载模组','Get the mod')} ↗</a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">${t('菜单','Menu')}</button></div></div>`;
 $('#footer').innerHTML=`<div class="container"><div class="footer-top"><div>${brand()}<p>${t('将遥远天体，写进你的法术书。<br>Iron’s Spells ’n Spellbooks 附属玩家百科。','Distant worlds, written in your spellbook.<br>A player reference for the Iron’s Spells ’n Spellbooks addon.')}</p></div><div class="footer-resources"><div class="footer-links"><a href="#/spells">${t('法术图鉴','Spell atlas')}</a><a href="#/text-effects">${t('文字特效工作台','Text effect workshop')}</a><a href="#/guide/faq">${t('常见问题','FAQ')}</a><a href="${cf}" target="_blank" rel="noopener noreferrer">CurseForge ↗</a></div>${contactDetails()}</div></div><div class="footer-bottom"><span>Iron’s Spells: Light Pollution · ${t('小刚同学','Xiaogang')}<br>${t('法术快照','Spell snapshot')} ${data.snapshot} · ${t('装备核对','Equipment checked')} ${window.WIKI_EQUIPMENT.snapshot} · ${t('含 1.7.7 待发布条目；以已安装版本为准。','Includes 1.7.7 previews; availability depends on your installed version.')}</span><a href="#/guide/credits">${t('关于本站与素材致谢','About this wiki & credits')}</a></div></div>`;
 $('#language').addEventListener('click',()=>{lang=lang==='zh'?'en':'zh';storage.set('lp-wiki-language',lang);render(false)});
 $('.menu-toggle').addEventListener('click',e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(open));$('#navigation').classList.toggle('open',open)});
}
function home(){
 const categories={gravity:'gargantua',stellar:'boreal_descent',domain:'astral_domain',nature:'world_tree',arcane:'astral_wings'};
 return `<section class="hero" aria-labelledby="home-title"><img class="hero-image" src="assets/media/mountains.jpg" alt="" width="1920" height="1280" fetchpriority="high"><div class="hero-content"><div class="eyebrow">IRON’S SPELLS: LIGHT POLLUTION</div><h1 id="home-title">${t('将星河，<span>写进你的法术书。</span>','A universe.<span>In your spellbook.</span>')}</h1><div class="hero-en">${t('A field guide to extraordinary magic.','THE SPELL ATLAS & PLAYER WIKI')}</div><p class="hero-description">${t('从黑洞的引力，到群星的坠落。<br>寻找你的下一个法术，读懂每一场天象。','From the pull of a black hole to the fall of distant stars.<br>Find your next spell. Learn the shape of its power.')}</p><div class="hero-actions"><a class="btn primary" href="#/spells">${t('探索法术图鉴','Explore the spell atlas')} ${forward}</a><a class="btn outline" href="#/guide/start">${t('第一次游玩','New to the mod?')}</a></div></div><div class="container hero-bottom"><span>MINECRAFT 1.20.1 &nbsp; / &nbsp; FORGE 47+</span><a class="scroll-down" href="#/spells">${t('开启探索','Begin exploring')} <span class="arrow" aria-hidden="true">↓</span></a><div class="hero-meta"><button class="motion-toggle" type="button" hidden><span data-motion-icon aria-hidden="true"></span><span data-motion-label></span></button><a class="photo-credit" href="#/guide/credits">${t('高山摄影 · 非游戏画面','Alpine photography · not gameplay')}</a></div></div></section>
 <div class="container"><div class="intro-strip"><p>${t('每个法术，都有自己的形态、节奏与应对方式。','Every spell has a shape, a rhythm, and a way to meet it.')}</p><div class="strip-stat"><strong>${data.spells.length}</strong><span>${t('图鉴条目 · 含待发布','Atlas entries · includes previews')}</span></div><div class="strip-stat"><strong>I — III</strong><span>${t('卷轴等级','Scroll tiers')}</span></div><div class="strip-stat"><strong>中 / EN</strong><span>${t('双语玩家百科','Bilingual player reference')}</span></div></div>
 <section class="section"><div class="section-head"><div><div class="eyebrow">THE OBSERVATORY</div><h2>${t('先看见，再理解。','See the spell. Know its power.')}</h2></div><p>${t('不同天象，不同战场。<br>从引力、空间与光开始认识这个世界。','Different skies. Different battlefields.<br>Start with gravity, space, and light.')}</p></div><div class="feature-grid"><a class="feature" href="#/spell/redshift_abyss"><div class="feature-art blackhole"><img src="assets/media/redshift.png" alt="${t('赤移天渊着色器预览：明亮吸积盘环绕暗色核心','Redshift Abyss shader preview: a bright disk around a dark core')}" width="640" height="360" loading="lazy"><span class="feature-caption">${t('着色器预览 · 非实机截图','Shader preview · not gameplay')}</span></div><div class="feature-body"><div><div class="eyebrow">01 / GRAVITY</div><h3>${t('赤移天渊','Redshift Abyss')}</h3><p>${t('光在此弯折，物质沿盘面旋入深渊。<br>查看引力牵引、吸积与终末坍缩。','Light bends. Matter spirals inward.<br>Explore orbital drag, accretion, and the final collapse.')}</p></div>${arrow}</div></a><a class="feature" href="#/spell/tesseract"><div class="feature-art"><img src="assets/media/tesseract-game.webp" alt="${t('超维折叠游戏画面：空中旋转的超立方体','Tesseract Fold in-game: a suspended hypercube')}" width="1280" height="720" loading="lazy"><span class="feature-caption">${t('游戏内截图 · 1.7.7 待发布','In-game capture · 1.7.7 preview')}</span></div><div class="feature-body"><div><div class="eyebrow">02 / DIMENSIONS</div><h3>${t('超维折叠','Tesseract Fold')}</h3><p>${t('四维旋转投下三维的影子。<br>三次空间脉冲之后，迎来最终收束。','A four-dimensional form casts a three-dimensional shadow.<br>Three pulses give way to one final collapse.')}</p></div>${arrow}</div></a></div>
 <div class="category-grid">${Object.entries(categories).map(([family,id])=>`<a class="category-tile" href="#/spells?family=${family}">${icon(spell(id))}<div><h3>${named(familyNames,family)}</h3><p>${data.spells.filter(s=>s.family===family).length} ${t('个条目','entries')} &nbsp; ↗</p></div></a>`).join('')}</div></section>
 <section class="section split-section"><div><div class="eyebrow">A LITTLE GUIDANCE</div><h2>${t('从第一张卷轴，<br>到你的群星之路。','From your first scroll<br>to a sky of your own.')}</h2><p>${t('找到配方、提升等级，把法术装入书与法杖。需要时，这里也有飞行操作、画面配置与常见问题。','Find a recipe, improve its tier, and inscribe it into a book or staff. Keep flight controls, visual settings, and practical answers close at hand.')}</p></div><div class="guide-links">${[['01','start'],['02','scrolls'],['03','config']].map(([index,id])=>`<a class="guide-link" href="#/guide/${id}"><span class="index">${index}</span><div><h3>${named(guideNames,id)}</h3><p>${id==='start'?t('版本、前置与安装','Versions, dependencies, and installation'):id==='scrolls'?t('合成、升级与铭刻','Crafting, upgrading, and inscription'):t('动态光照、提示框与帧率','Lighting, tooltips, and frame rate')}</p></div>${arrow}</a>`).join('')}</div></section>
 <section class="section"><div class="download-band"><div><div class="eyebrow">YOUR NEXT CHAPTER</div><h2 style="margin-top:16px">${t('让世界，亮一点。','Let your world shine.')}</h2><p>${t('通过 CurseForge 获取模组。安装前先查看版本与前置要求，联机双方需要安装相同版本。','Get the mod on CurseForge. Check the requirements first, and use matching addon versions on client and server.')}</p></div><a class="btn outline" href="${cf}" target="_blank" rel="noopener noreferrer">${t('前往下载','Get the mod')} ${arrow}</a></div></section></div>`;
}
function card(s){return `<a class="spell-card" href="#/spell/${s.id}"><div class="spell-card-top">${icon(s)}${s.pending?pending():`<span class="pill">${named(schoolNames,s.school)}</span>`}</div><div class="card-copy"><h3>${esc(local(s.name))}</h3><div class="alternate">${esc(s.name[lang==='zh'?'en':'zh'])}</div><p>${esc(local(s.description))}</p></div><div class="spell-card-bottom"><span>${named(rarityNames,s.rarity)}</span><span>${fmt(s.stats.manaCost)} ${t('法力','mana')}</span>${arrow}</div></a>`}
let filters;
function catalogue(params){
 filters={q:params.get('q')||'',school:params.get('school')||'',family:params.get('family')||'',version:params.get('version')||'',sort:params.get('sort')||'name'};
 if(!schoolNames[filters.school]) filters.school='';
 if(!familyNames[filters.family]) filters.family='';
 if(!['','pending','regular'].includes(filters.version))filters.version='';
 if(!['name','mana','cooldown'].includes(filters.sort))filters.sort='name';
 const options=(map,value,all)=>`<option value="">${all}</option>`+Object.keys(map).map(k=>`<option value="${k}" ${value===k?'selected':''}>${named(map,k)}</option>`).join('');
 return `<div class="container page-top"><div class="eyebrow">THE SPELL ATLAS</div><h1>${t('你的下一道法术。','Find your next spell.')}</h1><p class="lead">${t('按名称、学派或主题探索。每个条目都有合成配方、玩法说明和默认数值。','Explore by name, school, or theme. Every entry includes its recipe, gameplay description, and default statistics.')}</p></div><div class="container catalogue-layout"><aside class="catalogue-filters" aria-label="${t('学派筛选','Filter by school')}"><div class="eyebrow">${t('魔法学派','MAGIC SCHOOLS')}</div><div class="school-list">${['',...Object.keys(schoolNames)].map(k=>`<button class="school-filter" data-school="${k}" aria-pressed="${filters.school===k}">${k?named(schoolNames,k):t('全部学派','All schools')}<span>${data.spells.filter(s=>!k||s.school===k).length}</span></button>`).join('')}</div><p class="filters-note">${t('图鉴收录当前开发内容。标有「1.7.7 待发布」的法术，请等待对应版本。','This atlas includes development content. Entries marked “1.7.7 preview” require the corresponding future release.')}</p></aside><div><div class="search-row"><div class="search-wrap"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="search" type="search" autocomplete="off" aria-label="${t('搜索法术','Search spells')}" placeholder="${t('搜索中文名、英文名或关键词…','Search names, IDs, or keywords…')}" value="${esc(filters.q)}"><button class="clear-search" id="clear-search" aria-label="${t('清除搜索','Clear search')}" ${filters.q?'':'hidden'}>×</button></div><select id="family" aria-label="${t('按主题筛选','Filter by theme')}">${options(familyNames,filters.family,t('所有主题','All themes'))}</select></div><div class="catalogue-controls"><select id="version" aria-label="${t('内容版本','Content version')}"><option value="">${t('全部内容','All content')}</option><option value="regular" ${filters.version==='regular'?'selected':''}>${t('常规条目','Regular entries')}</option><option value="pending" ${filters.version==='pending'?'selected':''}>${t('1.7.7 待发布','1.7.7 previews')}</option></select><select id="sort" aria-label="${t('排序方式','Sort spells')}">${[['name',t('按名称排序','Sort by name')],['mana',t('法力从低到高','Lowest mana')],['cooldown',t('冷却从短到长','Shortest cooldown')]].map(([k,label])=>`<option value="${k}" ${filters.sort===k?'selected':''}>${label}</option>`).join('')}</select><span class="result-count" id="result-count" role="status" aria-live="polite"></span></div><div class="spell-grid" id="spell-results"></div><p class="view-note">${t('卡片显示 I 级默认法力；打开条目可切换 I–III 级。服务器配置与装备可能改变实际数值。','Cards show default tier-I mana. Open an entry to switch tiers I–III. Server settings and equipment may change actual values.')}</p></div></div>`;
}
function updateResults(persist=true){
 let list=data.spells.filter(s=>(!filters.school||s.school===filters.school)&&(!filters.family||s.family===filters.family)&&(!filters.version||(filters.version==='pending'?s.pending:!s.pending)));
 const q=filters.q.trim().toLocaleLowerCase();
 if(q)list=list.filter(s=>[...Object.values(s.name),...Object.values(s.description),s.id,...schoolNames[s.school],...familyNames[s.family]].join(' ').toLocaleLowerCase().includes(q));
 list.sort((a,b)=>filters.sort==='mana'?a.stats.manaCost-b.stats.manaCost:filters.sort==='cooldown'?a.stats.cooldownSeconds-b.stats.cooldownSeconds:local(a.name).localeCompare(local(b.name),lang==='zh'?'zh-CN':'en'));
 $('#spell-results').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><img src="assets/mark.svg" width="48" height="48" alt="" style="margin:auto;opacity:.5"><h3>${t('这片星空暂时没有结果。','No spells in this part of the sky.')}</h3><p>${t('试试其他关键词，或清除筛选查看全部法术。','Try another keyword or clear the filters to see every spell.')}</p><button class="btn" id="reset-filters">${t('清除所有筛选','Clear all filters')}</button></div>`;
 $('#result-count').textContent=t(`找到 ${list.length} / ${data.spells.length} 个法术`,`${list.length} of ${data.spells.length} spells`);
 $('#clear-search').hidden=!filters.q;
 document.querySelectorAll('[data-school]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.school===filters.school)));
 $('#reset-filters')?.addEventListener('click',()=>{history.replaceState(null,'','#/spells');render(false)});
 if(persist)window.WikiMotion?.results();
 if(persist){const p=new URLSearchParams();Object.entries(filters).forEach(([k,v])=>{if(v&&!(k==='sort'&&v==='name'))p.set(k,v)});history.replaceState(null,'',`#/spells${p.size?'?'+p:''}`)}
}
function bindCatalogue(){
 updateResults(false);
 $('#search').addEventListener('input',e=>{filters.q=e.target.value;updateResults()});
 $('#clear-search').addEventListener('click',()=>{$('#search').value='';filters.q='';updateResults();$('#search').focus()});
 for(const key of ['family','version','sort'])$('#'+key).addEventListener('change',e=>{filters[key]=e.target.value;updateResults()});
 document.querySelectorAll('[data-school]').forEach(b=>b.addEventListener('click',()=>{filters.school=b.dataset.school;updateResults()}));
}
const tips = {
 astral_wings:['施法展翼后双击跳跃起飞。跳跃上升、潜行下降；前进并疾跑加速，默认按 G 收翼。空中收翼会进入受控降落。','Cast to spread your wings, then double-tap jump to take off. Jump ascends, sneak descends, and moving forward while sprinting boosts. G folds the wings by default; in the air, this starts a controlled descent.'],
 pinwheel:['尘埃螺旋的臂间空隙可供躲避。观察旋转方向，及时穿过空隙，并为最后的双星爆发拉开距离。','Move through the gaps between the rotating dust arms, then gain distance before the final binary-star burst.'],
 cosmic_horseshoe:['伤害沿光环分布，终幕也只沿环命中。观察环的位置，避开环带。','Damage follows the ring, including the finale. Watch its position and stay clear of the annulus.'],
 thunder_retribution:['落点预告后有四轮范围雷雨，最后九雷齐落。实体屋顶可遮蔽雷击；九道可见雷光对每个目标只结算一次终罚。','Four area-lightning waves follow the warnings, then nine bolts strike together. Solid roofs provide shelter. The nine visible bolts apply the finale only once to each target.'],
 tesseract:['三次折叠脉冲后释放一次终爆。实体方块能阻挡伤害；保持距离，并留意核心收束的时机。','Three folding pulses lead into one final burst. Solid blocks can obstruct damage. Keep your distance and watch the core as it closes.'],
 jiuxiao_sword:['四道剑流先升空结阵，再追击附近敌对生物。所有目标共享一次施法的伤害预算，飞剑数量不等于每剑完整伤害。','Four sword streams rise into formation before pursuing nearby hostiles. All targets share one damage budget; each visible blade does not deal the full spell damage.'],
 boreal_descent:['落点伤害随距离衰减，看到预告后尽早远离。默认 J 可跳过当前运镜或切换运镜偏好；按键可以在设置中调整。','Impact damage falls with distance. Move away when a landing warning appears. J skips the current cinematic or toggles the camera preference by default; the binding can be changed.'],
 world_tree:['站在庇护范围内获得治疗与保护。它是支援法术，根系和树冠不会主动攻击。','Stay within its sanctuary for healing and protection. This is a support spell; its roots and crown do not attack.'],
 schwarzschild_lens:['这是纯视觉透镜法术。可附着已有黑洞，不额外增加伤害或牵引。','This lens is a visual spell. It can attach to an existing black hole and adds no extra damage or pull.'],
 spell_requiem:['队友可在开始后的 4 秒内加入仪式；无队伍玩家需在附近潜行施法主动加入，最多 8 人。光幕防御魔法，但近战与普通箭矢仍需应对。','Allies can join during the first four seconds. Unteamed players opt in by crouch-casting nearby, up to eight participants. The curtain protects against magic; melee attacks and ordinary arrows still matter.'],
 interdiction_field:['禁律会压制敌人的攻击、施法与普通传送；被困时仍可缓慢步行离开。','The field suppresses enemy attacks, spellcasting, and ordinary teleportation. A trapped player can still walk out slowly.'],
 umbral_prison:['击碎暗核可破阵。施法者潜行使用自己的阵眼，或输入 /closed_domain dismiss，可提前收回自己的领域。','Break the dark core to end the field. The caster can crouch-use their anchor or run /closed_domain dismiss to dismiss it.'],
 galactic_sanctum:['击碎星锚或脚下星结可解除领域。禁足仍允许瞄准、攻击、施法和使用物品。','Break a star anchor or the star knot beneath your feet to end the field. Rooted targets can still aim, attack, cast, and use items.'],
 chronal_court:['随时间推移，领域会侵蚀行动与防御。击碎阵眼解除领域；被禁足不代表无法反击。','The field gradually erodes movement and defenses. Break its anchor to escape; being rooted does not prevent you from fighting back.'],
 soul_shackles:['终结伤害取自其他敌人的实际有效受伤，并有上限。提前破阵或主动收回会取消终结一击。','The finale collects actual effective damage dealt to secondary enemies and is capped. Breaking or dismissing the field cancels the final strike.'],
 magnetic_charge:['主手或副手握住星磁弦弓后施法，补满三发。它不使用普通箭矢；箭矢命中后生成的奇点牵引十秒，再爆发。','Hold the Star-Magnet Bow in either hand and cast to refill three shots. It does not use ordinary arrows. An impact singularity pulls for ten seconds before bursting.'],
 absolute_extinction:['星门、贯星光束与行星裂解组成长演出。破裂行星是视觉场景，不会替换或破坏世界方块。','A long cinematic combines a gateway, a world-piercing beam, and a breaking planet. The planet is a visual scene and does not replace or destroy world blocks.'],
 world_devouring_dragon:['中国龙从裂隙中降临并进行六次穿行。门户、碎片与冲击是演出效果，真实地形保持不变。','A Chinese dragon emerges from a rift and makes six passages. Portals, fragments, and impacts are cinematic effects; the terrain stays intact.']
};
function recipe(s){
 const r=s.recipe;
 if(!r)return `<p>${t('此条目暂无收录配方，请以游戏内 JEI 为准。','No recipe is recorded for this entry. Check JEI in your installed version.')}</p>`;
 const cells=r.pattern.map(row=>row.padEnd(3,' ')).join('').padEnd(9,' ').split('');
 const counts={};cells.forEach(c=>{const i=r.key[c];if(i){const id=i.item||i.tag;counts[id]=(counts[id]||0)+1}});
 return `<div class="recipe-container"><div class="recipe-grid" role="group" aria-label="${t('三乘三工作台配方，从上到下、从左到右','Three-by-three crafting recipe, read row by row')}">${cells.map(c=>{const i=r.key[c];return i?itemButton(i.item||i.tag,ingredient(i.item||i.tag)):`<div class="ingredient blank" aria-label="${t('空格','Empty slot')}"></div>`}).join('')}</div>${forward}<div class="recipe-result">${itemButton(r.result.item,local(s.name)+t(' I 级卷轴',' · Tier-I scroll'),'recipe-output')}<p>${esc(local(s.name))}<br>${t('I 级卷轴','Tier-I scroll')}</p></div></div><p class="recipe-hint">${t('悬停或点按物品，查看名称与所属模组。','Hover or tap an item to see its name and source mod.')}</p><div class="ingredients-list">${Object.entries(counts).map(([id,n])=>`<div>${itemButton(id,ingredient(id),'material-icon')}<span>${esc(ingredient(id))}</span><span class="material-count">× ${n}</span></div>`).join('')}</div><p style="margin-top:20px;font-size:12px">${t('配方来自模组数据；整合包或数据包可能改动配方，请以当前游戏内 JEI 为准。','Recipes come from the mod data. Modpacks and datapacks can change them; use in-game JEI for your installation.')}</p>`;
}
function detail(s){
 const related=data.spells.filter(a=>a.id!==s.id&&a.family===s.family).slice(0,4);
 return `<div class="container page-top"><div class="breadcrumb"><a href="#/">${t('首页','Home')}</a><span>/</span><a href="#/spells">${t('法术图鉴','Spell atlas')}</a><span>/</span><span>${esc(local(s.name))}</span></div><div class="detail-top">${icon(s)}<div><div class="detail-tags"><span class="pill">${named(schoolNames,s.school)}</span><span class="pill">${named(rarityNames,s.rarity)}</span>${s.pending?pending():''}</div><h1>${esc(local(s.name))}</h1><div class="alternate">${esc(s.name[lang==='zh'?'en':'zh'])}</div></div></div></div><div class="container detail-layout"><article class="article">${s.pending?`<div class="notice">${t('这是 1.7.7 待发布内容。当前展示开发配置和配方，尚不代表已上线；最终内容以发布版本为准。','This is a 1.7.7 preview. The development settings and recipe shown here do not indicate a published release; the released version takes precedence.')}</div>`:''}<h2>${t('法术效果','What it does')}</h2><p>${esc(local(s.description))}</p>${tips[s.id]?`<h2>${t('使用与应对','Using and facing this spell')}</h2><p>${esc(t(...tips[s.id]))}</p>`:''}
 ${window.WikiShowcase?.markup(s,lang)||''}
 <h2>${t('合成配方','Crafting recipe')}</h2>${recipe(s)}<h2>${t('升级与铭刻','Upgrading & inscription')}</h2><p>${t('I 级卷轴搭配紫水晶碎片升级为 II 级；II 级搭配回响碎片升级为 III 级。使用铭刻台装入支持的法术书或法杖，保留卷轴等级。','Combine a tier-I scroll with an amethyst shard for tier II, then a tier-II scroll with an echo shard for tier III. Use an Inscription Table to put it into a supported spellbook or staff, retaining its tier.')}</p><p><a href="#/guide/scrolls">${t('阅读完整卷轴与升级指南','Read the scroll and upgrade guide')} →</a></p><h2>${t('继续探索','Continue exploring')}</h2><div class="related-list">${related.map(a=>`<a class="related-item" href="#/spell/${a.id}">${icon(a)}<span>${esc(local(a.name))}</span>${arrow}</a>`).join('')}</div><p class="view-note" style="margin-top:32px">${t('条目标识','Entry ID')}: <code>${esc(s.id)}</code><br>${t('内容核对日期','Content checked')}: ${data.snapshot}</p></article><aside class="stats-panel" aria-label="${t('法术默认数值','Default spell statistics')}"><h2>${t('法术数值','Spell statistics')}</h2><p>${t('默认配置 · 装备加成前','Default configuration · before gear bonuses')}</p><div class="level-switch" role="group" aria-label="${t('卷轴等级','Scroll tier')}">${[1,2,3].map((n)=>`<button data-level="${n}" aria-pressed="${n===1}" aria-label="${t('等级','Tier')} ${n}">${['I','II','III'][n-1]}</button>`).join('')}</div><div class="stats-values" id="stats-values"></div><p style="margin-top:20px">${t('伤害由具体阶段、目标类型、装备和服务器配置决定，不能直接从视觉规模推算。','Damage depends on the phase, target, equipment, and server settings. Visual scale does not determine damage.')}</p><button id="copy-link" class="btn">${t('复制此条目链接','Copy link to this spell')} ↗</button><p id="copy-result" role="status" style="margin-top:12px;overflow-wrap:anywhere"></p></aside></div>`;
}
function bindDetail(s){
 function level(n,animate=false){
  const mana=Math.floor((s.stats.manaCost*[100,85,70][n-1]+50)/100);
  const cd=Math.floor((s.stats.cooldownSeconds*20*[100,80,65][n-1]+50)/100)/20;
  $('#stats-values').innerHTML=[[t('法力消耗','Mana cost'),fmt(mana)],[t('冷却时间','Cooldown'),fmt(cd)+t(' 秒',' s')],[t('吟唱时间','Cast time'),fmt(s.stats.castTimeTicks/20)+t(' 秒',' s')]].map(([key,val])=>`<div class="stat-row"><span>${key}</span><strong>${val}</strong></div>`).join('');
  document.querySelectorAll('[data-level]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.level===n)));
  if(animate)window.WikiMotion?.feedback($('#stats-values'));
 }
 level(1);document.querySelectorAll('[data-level]').forEach(b=>b.addEventListener('click',()=>level(+b.dataset.level,true)));
 $('#copy-link').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);$('#copy-result').textContent=t('链接已复制。','Link copied.')}catch{$('#copy-result').textContent=t('请复制此地址：','Copy this address: ')+location.href}});
}
const para = (zh,en) => `<p>${t(zh,en)}</p>`;
const heading = (zh,en) => `<h2>${t(zh,en)}</h2>`;
const command = text => `<div class="command"><code>${esc(text)}</code><button data-copy="${esc(text)}">${t('复制','Copy')}</button></div>`;
function guideBody(id){
 if(id==='start')return heading('准备你的世界','Prepare your world')+para('本模组是 Iron’s Spells ’n Spellbooks 的附属。请使用 Minecraft 1.20.1、Forge 47+ 和 Java 17，并安装铁魔法本体、Iron’s Lib 及它们要求的依赖。','This is an addon for Iron’s Spells ’n Spellbooks. Use Minecraft 1.20.1, Forge 47+, and Java 17, with the base mod, Iron’s Lib, and all dependencies they require.')+`<div class="table-wrap"><table><thead><tr><th>${t('组件','Component')}</th><th>${t('要求','Requirement')}</th></tr></thead><tbody><tr><td>Minecraft</td><td>1.20.1</td></tr><tr><td>Forge</td><td>47+</td></tr><tr><td>Java</td><td>17</td></tr><tr><td>Iron’s Spells ’n Spellbooks</td><td>1.20.1-3.16.1+</td></tr><tr><td>Iron’s Lib</td><td>1.20.1-1.1.0+</td></tr></tbody></table></div>`+heading('安装与联机','Install and play together')+`<ol><li>${t('从 CurseForge 下载与你的游戏版本匹配的模组文件。','Download a file matching your game version from CurseForge.')}</li><li>${t('关闭游戏，将附属与所需前置放入该实例的 mods 文件夹，再启动 Forge。','Close Minecraft, put the addon and required dependencies in the instance’s mods folder, then start Forge.')}</li><li>${t('联机时，服务器和每位玩家都要安装相同版本的本附属。','For multiplayer, the server and every player need matching versions of this addon.')}</li><li>${t('进入世界后，在 JEI 搜索目标卷轴，按配方合成，再到铭刻台装配。','In your world, search JEI for a scroll, craft it, and inscribe it at an Inscription Table.')}</li></ol><a class="btn primary" href="${cf}" target="_blank" rel="noopener noreferrer">${t('前往 CurseForge 下载','Download on CurseForge')} ${arrow}</a>`+heading('先从哪里开始','Where to begin')+para('想自由探索，可以先看星穹之翼；偏好支援，可以查看世界树；喜欢天体演出，可以从赤移天渊或北斗天坠开始。先确认法力是否充足，再选择适合的卷轴。','For exploration, start with Astral Wings. For support, try World Tree. For astronomical spectacles, browse Redshift Abyss or Boreal Descent. Check your mana before choosing a scroll.')+`<p><a href="#/spells">${t('浏览全部法术','Browse every spell')} →</a></p>`;
 if(id==='scrolls')return heading('获取第一张卷轴','Get your first scroll')+para('法术图鉴的每个条目都展示已收录的生存合成配方。卷轴也接入宝箱战利品；具体宝箱与概率由模组和整合包配置决定。JEI 可以核对当前环境中的实际配方。','Every spell entry includes its recorded survival crafting recipe. Scrolls also appear in chest loot; chest types and chances depend on mod and modpack settings. JEI shows the recipe for your current installation.')+heading('I → II → III','I → II → III')+`<div class="table-wrap"><table><thead><tr><th>${t('目标','Upgrade')}</th><th>${t('材料','Ingredients')}</th></tr></thead><tbody><tr><td>I → II</td><td>${t('I 级卷轴 + 紫水晶碎片','Tier-I scroll + amethyst shard')}</td></tr><tr><td>II → III</td><td>${t('II 级卷轴 + 回响碎片','Tier-II scroll + echo shard')}</td></tr></tbody></table></div>`+para('升级降低法力消耗与有效冷却。通用伤害倍率如下；治疗、控制、飞行时长等仍使用各法术自己的规则。纯视觉法术升级后也不会凭空增加伤害。','Upgrades reduce mana cost and effective cooldown. Shared damage multipliers are listed below; healing, control, and flight duration follow the individual spell’s rules. Visual-only spells remain non-damaging.')+`<div class="table-wrap"><table><thead><tr><th>${t('等级','Tier')}</th><th>${t('通用伤害倍率','Shared damage multiplier')}</th><th>${t('法力倍率','Mana multiplier')}</th><th>${t('冷却倍率','Cooldown multiplier')}</th></tr></thead><tbody><tr><td>I</td><td>1.00×</td><td>1.00×</td><td>1.00×</td></tr><tr><td>II</td><td>1.35×</td><td>0.85×</td><td>0.80×</td></tr><tr><td>III</td><td>1.75×</td><td>0.70×</td><td>0.65×</td></tr></tbody></table></div>`+heading('装入法术书或法杖','Inscribe a book or staff')+para('在铁魔法的铭刻台放入受支持的法术书或法杖，以及目标卷轴。写入后保留法术等级。星海权杖的 12 槽与无垠星海的 24 槽装配支持属于 1.7.7 更新内容。','At an Inscription Table, insert a supported spellbook or staff and the chosen scroll. Inscription preserves its tier. The Astral Staff’s 12-slot and Endless Starsea’s 24-slot inscription support is part of the 1.7.7 update.')+`<p><a href="#/equipment">${t('查看装备说明','See the equipment guide')} →</a></p>`;
 if(id==='flight')return heading('展翼与起飞','Spread your wings')+para('施放星穹之翼后等待展翼，双击跳跃起飞。空中施法会先止坠，再接入飞行。法术持续时间在地面也会流逝，待飞时不收取维持法力。','Cast Astral Wings, wait for the wings to open, then double-tap jump to take off. Casting in the air first arrests the fall. Duration continues on the ground, but waiting to take off consumes no upkeep mana.')+`<div class="table-wrap"><table><thead><tr><th>${t('操作','Action')}</th><th>${t('默认控制','Default control')}</th></tr></thead><tbody>${[[t('水平移动','Move horizontally'),'W / A / S / D'],[t('上升','Ascend'),t('跳跃','Jump')],[t('下降','Descend'),t('潜行','Sneak')],[t('加速','Boost'),t('前进 + 疾跑','Forward + sprint')],[t('收翼 / 受控降落','Fold wings / controlled descent'),'G']].map(a=>`<tr><td>${a[0]}</td><td>${a[1]}</td></tr>`).join('')}</tbody></table></div>`+heading('法力与降落','Mana and landing')+para('默认普通飞行每秒消耗 2 法力，加速飞行每秒总计 6 法力。法力耗尽、持续时间结束或空中收翼时，进入安全下降；落地后效果结束。请在游戏按键设置中检查冲突和改绑。','Normal flight costs 2 mana per second by default; boosting costs 6 mana per second in total. Running out of mana, expiring, or folding in midair starts a controlled descent. Check key conflicts and bindings in Minecraft’s controls.')+`<p><a href="#/spell/astral_wings">${t('查看星穹之翼配方与法力','View the Astral Wings recipe and mana cost')} →</a></p>`;
 if(id==='equipment')return `<p><a class="text-link" href="#/equipment">${t('打开武器图鉴：外观、属性与完整配方','Open the armoury: appearance, attributes and full recipes')} →</a></p>`+heading('永恒星光','Eternal Starlight')+para('1.7.7 待发布的新武器。基础攻击伤害 24、攻击速度 1.6。近战命中出现弦月裂斩与延迟三星残像；按住右键蓄力 0.9 秒，随后沿准星方向释放最长十秒、最远 64 格的虚空光束。松开右键收束，遇实体方块截断。光束单次基础伤害 12。封魔斩封锁铁魔法施法，裂界刻印强化自己的光束，终夜裁决增伤低生命目标；持续时间、冷却与首领规则见武器详情。普通单体近战遵守 PvP 与队伍规则，光束排除所有玩家；特殊攻击保护有主宠物、友方与地形。','An upcoming 1.7.7 weapon with 24 base attack damage and 1.6 attack speed. Melee hits draw a crescent slash followed by a three-star afterimage. Hold right-click for a 0.9-second charge, then aim a void beam for up to ten seconds and 64 blocks. Release to end it; solid blocks stop it. Base damage per beam hit is 12. Spellseal blocks Iron’s spellcasting, Rift Mark strengthens your own beam, and Nightfall Verdict boosts damage against low-health targets; see the weapon page for durations, cooldowns and boss rules. Ordinary single-target melee respects PvP and team rules; beams exclude all players. Special attacks protect owned pets, allies and terrain.')+`<p><a href="#/equipment/nocturne_verdict">${t('查看永恒星光外观与配方','View Eternal Starlight and its recipe')} →</a></p>`+heading('紫晶裂地斧','Amethyst Riftcleaver')+para('1.7.7 待发布：左键投出回旋斧；按住右键至少 0.3 秒后松开施展重投，蓄力 1 秒达到满蓄力。近战面板伤害 21，攻击速度 1.0；回旋投掷基础伤害 21，重击中心基础伤害最高 42，实际仍受加成、平衡倍率和减伤影响。晶蚀削减护甲，回旋共鸣强化返程命中，撼地使目标虚弱。投斧保护玩家、友方、有主宠物与地形。','1.7.7 preview: left-click throws a returning axe; hold right-click for at least 0.3 seconds, then release for a heavy throw. Full charge takes 1 second. Displayed melee damage is 21, with 1.0 attack speed; base throw damage is 21, with up to 42 base damage at the heavy-impact center. Bonuses, balance multipliers and mitigation affect actual damage. Crystal Erosion reduces armor, Returning Resonance rewards return hits, and Earthshaker inflicts Weakness. Throws protect players, allies, owned pets and terrain.')+`<p><a href="#/equipment/amethyst_riftcleaver">${t('查看紫晶裂地斧的三项属性与配方','View the axe’s three traits and recipe')} →</a></p>`+heading('金珀蜂刺','Amber Sting')+para('1.7.7 待发布：近战面板伤害 14，攻击速度 2.2；蓄力投掷后触发两次落地冲击，满蓄力基础伤害分别为 20、28。蜜缚使目标缓慢，蜂群印强化第三击，采蜜归巢在有效伤敌的飞行返手时恢复生命。普通单体近战遵守 PvP 与队伍规则；投掷冲击排除所有玩家，并保护友方、有主宠物与地形。','1.7.7 preview: displayed melee damage is 14, with 2.2 attack speed. Charge and throw to trigger two ground impacts, dealing 20 and 28 base damage at full charge. Honeybind slows enemies, Swarm Mark boosts the third hit, and Homecoming Harvest heals you when a throw that damaged an enemy returns. Ordinary single-target melee respects PvP and team rules; thrown impacts exclude all players and protect allies, owned pets and terrain.')+`<p><a href="#/equipment/amber_sting">${t('查看金珀蜂刺的三项属性与配方','View the dagger’s three traits and recipe')} →</a></p>`+heading('星海权杖与无垠星海','Astral staves')+para('星海权杖与无垠星海在主手持有时分别提供 +1500 / +3000 最大法力，并提供通用法术属性。卸下后超出新上限的法力会被截断，重新装备不会自动回满。','The Astral Staff and Endless Starsea grant +1500 / +3000 maximum mana and universal spell attributes while held in the main hand. Removing them clips mana above the new limit; equipping them does not refill it.')+`<div class="notice">${t('1.7.7 待发布：星海权杖可装配 12 个法术，无垠星海可装配 24 个；高阶法杖每页显示 12 槽。','1.7.7 preview: the Astral Staff holds 12 spells; Endless Starsea holds 24, displayed in pages of 12.')}</div>`+para('在铭刻台装配与取出法术。手持法杖后，使用铁魔法的法术选择功能，并右键施放。升级保留已装配的法术、等级、槽位、名称和附魔。','Add or remove spells at an Inscription Table. Hold the staff, select a spell through Iron’s Spells’ spell-selection controls, then right-click to cast. Upgrading retains inscribed spells, tiers, slots, name, and enchantments.')+heading('星磁弦弓','Star-Magnet Bow')+para('这把弓不能附魔，也不使用普通箭矢。握在任意一只手中，施放星磁赋能可补满三发。射出的箭可以穿透实体，遇到实体方块碰撞形状会停止。命中后的磁力奇点持续牵引十秒，随后爆发，不破坏方块。','This bow cannot be enchanted and does not use ordinary arrows. Hold it in either hand and cast Magnetic Imbuement to refill three shots. Arrows pierce entities but stop at solid block collision shapes. An impact singularity pulls for ten seconds and then detonates without destroying blocks.')+para('1.7.7 待发布：藏宝图指向的埋藏宝藏箱有 25% 概率额外生成不周山秘录。右键阅读后解锁星磁弦弓配方；已经生成过战利品的旧箱子不会补发。','1.7.7 preview: buried-treasure chests located by treasure maps have a 25% chance to include the Buzhou Mountain Codex. Read it to unlock the bow recipe. Chests that have already generated their loot are not refilled.')+`<p><a href="#/spell/magnetic_charge">${t('查看星磁赋能','Read about Magnetic Imbuement')} →</a></p>`;
 if(id==='config')return heading('先分清玩法与画面','Gameplay and visuals')+para('伤害、法力和冷却由服务器控制；客户端亮度或画面尺寸不会改变真实伤害范围。更改配置后，部分参数需要重新施法才会应用。修改前先备份自己的配置。','The server controls damage, mana, and cooldowns. Client brightness and visual size do not change damage ranges. Some settings are captured at cast time and take effect on your next cast. Back up your configuration before editing.')+`<div class="table-wrap"><table><thead><tr><th>${t('用途','Purpose')}</th><th>${t('位置','Location')}</th></tr></thead><tbody><tr><td>${t('当前世界的主要玩法配置','Main gameplay settings for the world')}</td><td><code>&lt;world&gt;/serverconfig/irons_spellbooks_light_pollution-server.toml</code></td></tr><tr><td>${t('本机光照与视觉','Local lighting and visuals')}</td><td><code>config/irons_spellbooks_light_pollution-client.toml</code></td></tr><tr><td>${t('黑洞画质','Black-hole quality')}</td><td><code>config/irons_spellbooks_light_pollution-black-holes.toml</code></td></tr></tbody></table></div>`+para('新法术还可能生成独立配置文件。单人存档的服务端配置位于 saves/&lt;world&gt;/serverconfig/；defaultconfigs 只给新世界提供默认值，不覆盖旧存档。','New spells may also create dedicated configuration files. Single-player server settings live in saves/&lt;world&gt;/serverconfig/. The defaultconfigs folder seeds new worlds; it does not override existing saves.')+heading('提示框与伤害数字','Tooltips and damage numbers')+para('七种可选提示框样式默认关闭，可通过 tooltipStyle 选项选择。浮动伤害数字同样默认关闭，会将目标短时间内的连续伤害合并显示。','Seven optional tooltip styles are off by default and can be selected with tooltipStyle. Floating damage numbers are also off by default and merge continuous damage to one target over a short interval.')+command('/lightpollution damage on')+command('/lightpollution damage off')+heading('光影与性能','Shaders and performance')+para('动态彩色照明独立于原版方块亮度，不会改变刷怪条件。不需要额外光影包就能使用模组光照。已记录测试的组合为 Oculus 1.8.0、Embeddium 0.3.31 与 Complementary Reimagined r5.8.1，其他组合仍需自行核对。','Dynamic coloured lighting is independent of vanilla block light and does not change spawning conditions. It works without a shader pack. The documented tested setup uses Oculus 1.8.0, Embeddium 0.3.31, and Complementary Reimagined r5.8.1; other combinations need their own checks.')+para('如果帧率下降，先降低黑洞画质与同时可见的复杂法术数量，再调整粒子、光照或独立视觉配置。终爆反馈提供标准、轻量和关闭模式，可按偏好减少画面停顿与震动。','If frame rate drops, lower black-hole quality and the number of complex spells visible at once, then adjust particles and lighting. Impact feedback offers standard, light, and off modes to reduce visual holds and camera movement.');
 if(id==='faq')return [
 ['联机只在客户端装可以吗？','Can I install it on the client only?','不可以。服务器也需要注册法术实体与伤害类型，请让客户端和服务器安装相同版本。','No. The server also registers spell entities and damage types. Use matching versions on both sides.'],
 ['为什么找不到图鉴里的某个法术？','Why is a spell missing from my game?','先检查条目是否标有「1.7.7 待发布」。再核对模组版本、服务器配置和 JEI，整合包也可能调整获取方式。','First check for the “1.7.7 preview” badge. Then check your addon version, server settings, and JEI. Modpacks can also alter acquisition.'],
 ['数值和我游戏里的不同？','Why are my statistics different?','图鉴展示开发快照中的默认配置。服务器调整、法术等级、装备、状态和整合包都可能改变实际数值，游戏内当前提示优先。','The wiki shows default settings from its content snapshot. Server configuration, tier, equipment, effects, and modpacks can change values. Current in-game tooltips take precedence.'],
 ['动态光照会让怪物不再生成吗？','Does spell lighting stop mobs spawning?','不会。它不改写原版方块亮度，也不改变读取原版亮度的玩法规则。','No. It does not change vanilla block-light levels or gameplay rules that read them.'],
 ['必须装光影才能看到特效吗？','Do I need a shader pack?','不需要。模组有自己的渲染与光照。外部光影的兼容范围请看配置与性能指南。','No. The addon has its own rendering and lighting. See the settings guide for the documented external-shader setup.'],
 ['行星爆裂和中国龙会拆掉建筑吗？','Do the breaking planet and dragon destroy buildings?','待发布的绝对灭绝与吞世天龙都将演出和真实地形分开：保留裂解、穿行、碎片和冲击，真实方块保持不变。','The upcoming Absolute Extinction and World Devouring Dragon separate their spectacle from terrain: breaking, passages, fragments, and impacts keep real world blocks intact.'],
 ['如何主动结束自己的封闭领域？','How do I dismiss my closed domain?','潜行使用自己的阵眼，或输入 /closed_domain dismiss。主动收回会取消终结一击。','Crouch-use your own anchor or run /closed_domain dismiss. Dismissing cancels the final strike.']
 ].map(([zh,en,a,b])=>`<details><summary>${t(zh,en)}</summary><p>${t(a,b)}</p></details>`).join('');
 if(id==='updates')return `<div class="notice">${t('本页是内容版本指引，不是发布公告。当前工程版本为 1.7.6，以下内容归入待发布的 1.7.7；可下载文件以 CurseForge 页面为准。','This page is a content guide, not a release announcement. The project version is 1.7.6; the changes below belong to the pending 1.7.7 update. Check CurseForge for downloadable releases.')}</div>`+heading('1.7.7 · 待发布','1.7.7 · Upcoming')+`<ul><li>${t('四个新增法术：超维折叠、逆霆天罚、绝对灭绝、吞世天龙。','Four new spells: Tesseract Fold, Thunder Reprisal, Absolute Extinction, and World Devouring Dragon.')}</li><li>${t('星穹之翼的羽片材质、扑翼动作、转向与滑翔过渡改进。','Refinements to Astral Wings materials, flapping, turns, and glide transitions.')}</li><li>${t('星海权杖 12 槽、无垠星海 24 槽法术装配与分页。','Spell inscription for the 12-slot Astral Staff and 24-slot Endless Starsea.')}</li><li>${t('埋藏宝藏中的不周山秘录获取途径。','A buried-treasure acquisition route for the Buzhou Mountain Codex.')}</li><li>${t('终爆反馈、物品提示颜色、喷流命中等改进与修复。','Improvements and fixes to impact feedback, tooltip colours, and jet targeting.')}</li></ul><p><a href="#/spells?version=pending">${t('只看待发布法术','Browse upcoming spells')} →</a></p>`+heading('武器图鉴补充 · 2026-11-08','Armoury update · 2026-11-08')+para('武器图鉴扩展为六件装备，新增紫晶裂地斧与金珀蜂刺。三把武器的九项战斗特性已补齐，包含触发条件、持续时间、冷却、首领效果及伤害保护规则；近战面板伤害更新为 24 / 21 / 14，技能伤害与合成链同步核对。','The armoury now covers six weapons, adding Amethyst Riftcleaver and Amber Sting. All nine combat traits of the three weapons include triggers, durations, cooldowns, boss effects and targeting protections. Displayed melee damage is updated to 24 / 21 / 14, with skill damage and component recipes checked alongside it.')+`<p><a href="#/equipment">${t('打开武器图鉴','Open the armoury')} →</a></p>`+heading('关于图鉴内容','About the catalogue')+para('本站在 2026-11-07 核对了 48 个注册条目的中英名称、学派、默认法力、吟唱、冷却和卷轴配方。玩法文案来自本项目的语言资源与玩家说明。更新中的内容仍可能变化。','On 2026-11-07, this wiki checked the names, schools, default mana, cast time, cooldown, and scroll recipes of 48 registered entries. Gameplay text is based on the mod’s language resources and player documentation. Content in development may still change.');
 if(id==='credits')return heading('武器外观素材','Weapon appearance assets')+para('武器图鉴使用原始模型和贴图生成静态外观图，并附已有开发版 Minecraft 实机截图。静态模型图不包含完整游戏描边与动画。永恒星光、紫晶裂地斧与金珀蜂刺分别采用作者提供的 Nazgul Fantasy Weaponry VANILLA Vol. 5 下界之星剑、紫水晶斧与蜜蜂匕首模型；原素材权利与署名归其创作者。','The armoury pairs static renders of original geometry and textures with existing Minecraft development screenshots. Static views do not include the full in-game outlines or animation. Eternal Starlight, Amethyst Riftcleaver and Amber Sting use the Nether Star Sword, Amethyst Axe and Bee Dagger models supplied by the project owner from Nazgul Fantasy Weaponry VANILLA Vol. 5; its creators retain their rights and attribution.')+heading('关于这本图鉴','About this atlas')+para('这里是铁魔法：光污染的独立玩家百科，提供法术查询、配方与玩法指南。模组作者：小刚同学。本站不属于 Minecraft、Mojang 或 Microsoft 官方网站。','This independent player wiki for Iron’s Spells: Light Pollution provides spell lookup, recipes, and practical guides. Mod author: Xiaogang. This is not an official Minecraft, Mojang, or Microsoft website.')+heading('联系方式','Contact')+contactDetails()+heading('视觉与素材','Design & imagery')+`<ul><li>${t('界面参考','Interface direction')}: <a href="https://styles.refero.design/style/3172cd4d-118a-4a16-a259-6b634d32322e" target="_blank" rel="noopener noreferrer">Mercury — Refero Styles</a>. ${t('使用其配色、留白与控件形态，品牌与页面内容为本站设计。','Its palette, spacing, and control shapes inform the design; the wiki has its own identity and content.')}</li><li>${t('首页高山摄影：Unsplash 图片资源。仅作氛围背景，不是游戏画面。','Homepage mountain photography: Unsplash image resource, used as atmosphere rather than gameplay imagery.')} <a href="https://images.unsplash.com/photo-1464822759023-fed622ff2c3b" target="_blank" rel="noopener noreferrer">${t('原图','Original image')}</a> · <a href="https://unsplash.com/license" target="_blank" rel="noopener noreferrer">${t('许可','License')}</a></li><li>${t('字体遵循 Mercury 规范中的 Arcadia / Arcadia Display 声明与系统字体回退链。本站未附带这两款字体文件，实际显示使用设备可用的字体。','Typography follows the supplied Arcadia / Arcadia Display declarations and system font fallback stack. These font files are not bundled; the browser uses fonts available on the device.')}</li><li>${t('法术图标来自本模组资源。48 个法术的效果展示均为 Minecraft 客户端实机录像，采用 2026-11-07 开发快照，720p、24 fps、无声、未使用外部光影包。缺少专属图标的开发条目使用本站通用标志。','Spell icons come from the mod. All 48 spell showcases are recorded in Minecraft using development snapshots from 2026-11-07: 720p, 24 fps, silent, without an external shader pack. Development entries without an icon use the wiki’s general mark.')}</li></ul>`+heading('内容与版本','Content & versions')+para('法术名、默认值和配方取自同日内容快照。配方中的物品贴图来自 Minecraft 1.20.1 与 Iron’s Spells ’n Spellbooks 3.16.1，方块图标根据原始模型和贴图生成。模组第三方组成部分的权利与致谢仍遵循原项目声明，本站不改变这些许可。请以实际游戏版本、服务器配置与最新模组发布说明为准。','Names, defaults, and recipes come from the dated content snapshot. Recipe textures come from Minecraft 1.20.1 and Iron’s Spells ’n Spellbooks 3.16.1; block icons are rendered from their original models and textures. Third-party components retain the rights and attribution stated by the mod; this wiki does not change their licences. Your game version, server configuration, and current release notes take precedence.');
 return '';
}
function guide(id){return `<div class="container page-top"><div class="breadcrumb"><a href="#/">${t('首页','Home')}</a><span>/</span><span>${t('玩家指南','Player guide')}</span></div><div class="eyebrow">THE FIELD GUIDE</div><h1>${named(guideNames,id)}</h1></div><div class="container guide-layout"><nav class="guide-nav" aria-label="${t('指南目录','Guide navigation')}">${Object.keys(guideNames).map(k=>`<a href="#/guide/${k}" ${id===k?'aria-current="page"':''}>${named(guideNames,k)}</a>`).join('')}</nav><article class="article guide-article">${guideBody(id)}</article></div>`}
function equipment(id){return window.WikiEquipment.render(lang,id,{itemButton})}
function render(move=true){
 window.WikiTextEffects?.reset();
 window.WikiShowcase?.reset();
 window.WikiMotion?.reset();
 hideItemTooltip();
 const raw=(location.hash||'#/').slice(1), [path,query='']=raw.split('?'),route=path||'/';
 chrome(route);
 let html,title=t('光污染 · 法术百科','Light Pollution · Spell Atlas');
 if(route==='/')html=home();
 else if(route==='/spells'){html=catalogue(new URLSearchParams(query));title=t('法术图鉴','Spell atlas')+' · Light Pollution'}
 else if(route.startsWith('/spell/')&&spell(route.slice(7))){const s=spell(route.slice(7));html=detail(s);title=local(s.name)+' · Light Pollution Wiki'}
 else if(route.startsWith('/guide/')&&guideNames[route.slice(7)]){html=guide(route.slice(7));title=named(guideNames,route.slice(7))+' · Light Pollution Wiki'}
 else if(route==='/text-effects'){html=window.WikiTextEffects.page(lang);title=t('文字特效工作台','Text effect workshop')+' · Light Pollution Wiki'}
 else if(route==='/equipment'){html=equipment();title=t('武器与装备','Weapons & equipment')+' · Light Pollution Wiki'}
 else if(route.startsWith('/equipment/')&&window.WikiEquipment.find(route.slice(11))){const w=window.WikiEquipment.find(route.slice(11));html=equipment(w.id);title=local(w.name)+' · Light Pollution Wiki'}
 else html=`<div class="error-page"><div class="eyebrow">404 / UNCHARTED SPACE</div><h1>${t('这颗星，还不在图鉴里。','This star is not in the atlas.')}</h1><p>${t('链接可能有误。回到图鉴继续寻找法术。','This link may be incorrect. Return to the atlas to find a spell.')}</p><a class="btn primary" href="#/spells">${t('返回法术图鉴','Back to the atlas')} ${forward}</a></div>`;
 $('#main').innerHTML=html;document.title=title;
 if(route==='/spells')bindCatalogue();
 if(route.startsWith('/spell/')&&spell(route.slice(7)))bindDetail(spell(route.slice(7)));
 bindItems();
 if(route.startsWith('/equipment/'))window.WikiEquipment.mount(route.slice(11));
 document.querySelectorAll('[data-copy]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent=t('已复制','Copied');$('#announcement').textContent=t('命令已复制','Command copied')}catch{$('#announcement').textContent=t('无法自动复制，请选中命令文本复制。','Automatic copying is unavailable. Select and copy the command text.');b.textContent=t('请手动复制','Copy manually')}}));
 if(move){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true})}
 window.WikiMotion?.mount();
 window.WikiShowcase?.mount(lang);
 if(route==='/text-effects')window.WikiTextEffects.mount(lang);
}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideItemTooltip();$('#navigation')?.classList.remove('open');$('.menu-toggle')?.setAttribute('aria-expanded','false')}});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.item-trigger,#item-tooltip'))hideItemTooltip()});
$('#item-tooltip').addEventListener('pointerenter',()=>clearTimeout(tooltipTimer));
$('#item-tooltip').addEventListener('pointerleave',hideItemTooltip);
window.addEventListener('scroll',hideItemTooltip,{passive:true});
window.addEventListener('resize',hideItemTooltip);
window.addEventListener('hashchange',()=>render());
render(false);
})();
